/// @slider 0 2.5E+3
/// @sort 32
uniform float Range = 1e3;
/// @sort 32
uniform float Falloff = 2.5e-1f;
static const float Bias = -1.5e2;
// A scalar default or slider bound written with an exponent is a number, as 1.x read it.
/// @name M_LpExponent
export void M_LpExponent(inout material Base)
{
    float Alpha = 0;
    Alpha = Range * Falloff + Bias;
    Base.Opacity = Alpha;
}
